 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
	id("org.openjfx.javafxplugin") version "0.1.0"
}

javafx {
    version = "21.0.5"
    modules("javafx.controls", "javafx.web")
}


repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    testImplementation(libs.junit.jupiter)
    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
    implementation(libs.guava)

	implementation("org.jdbi:jdbi3-core:3.55.0")
	implementation("org.jdbi:jdbi3-sqlite:3.55.0")
	implementation("org.jdbi:jdbi3-sqlobject:3.55.0")
	implementation("org.xerial:sqlite-jdbc:3.54.1.0")   

	runtimeOnly("org.slf4j:slf4j-simple:2.0.16")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(17)
    }
}

application {
    // Define the main class for the application.
    mainClass = "net.tarou.Main"
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

val frontendDir = rootProject.file("frontend")

val npmBuild by tasks.registering(Exec::class) {
    workingDir = frontendDir
    commandLine("npm", "run", "build")
    inputs.dir(frontendDir.resolve("src"))
    inputs.file(frontendDir.resolve("package.json"))
    inputs.file(frontendDir.resolve("vite.config.ts"))
    outputs.dir(frontendDir.resolve("dist"))
}

tasks.named<ProcessResources>("processResources") {
    dependsOn(npmBuild)
    from(frontendDir.resolve("dist")) {
        into("web")
    }
}
